CREATE OR REPLACE FUNCTION stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.check_stock_initial_complete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE opening stock_initial_openings%ROWTYPE; expected integer;
BEGIN
  SELECT * INTO opening FROM stock_initial_openings WHERE id=NEW.id;
  expected:=jsonb_array_length(opening.payload->'entries');
  IF opening.result IS NULL OR expected IS NULL OR expected<1
    OR (SELECT count(*) FROM stock_batches WHERE stock_initial_id=opening.id)<>expected
    OR (SELECT count(*) FROM stock_movements WHERE stock_initial_id=opening.id)<>expected THEN
    RAISE EXCEPTION 'Incomplete STOCK_INITIAL transaction' USING ERRCODE='23514';
  END IF;
  IF EXISTS(
    (SELECT e->>'product_id', e->>'unit', (e->>'quantity')::numeric, (e->>'expiration_date')::date
      FROM jsonb_array_elements(opening.payload->'entries') e
     EXCEPT ALL
     SELECT product_id::text,unit,initial_quantity,expiration_date FROM stock_batches WHERE stock_initial_id=opening.id)
    UNION ALL
    (SELECT product_id::text,unit,initial_quantity,expiration_date FROM stock_batches WHERE stock_initial_id=opening.id
     EXCEPT ALL
     SELECT e->>'product_id', e->>'unit', (e->>'quantity')::numeric, (e->>'expiration_date')::date
      FROM jsonb_array_elements(opening.payload->'entries') e)
  ) THEN RAISE EXCEPTION 'STOCK_INITIAL manifest does not match batches' USING ERRCODE='23514'; END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.gs_polygon_from_location(location_value jsonb)
 RETURNS geometry
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  ring JSONB;
  point JSONB;
  coords TEXT := '';
  first_lng DOUBLE PRECISION;
  first_lat DOUBLE PRECISION;
  last_lng DOUBLE PRECISION;
  last_lat DOUBLE PRECISION;
  lng DOUBLE PRECISION;
  lat DOUBLE PRECISION;
  count_points INTEGER := 0;
BEGIN
  IF location_value IS NULL THEN
    RETURN NULL;
  END IF;

  IF jsonb_typeof(location_value) = 'string' THEN
    RETURN gs_polygon_from_location((location_value #>> '{}')::JSONB);
  END IF;

  IF location_value ? 'type'
     AND lower(location_value->>'type') = 'polygon'
     AND location_value ? 'coordinates' THEN
    RETURN ST_SetSRID(ST_GeomFromGeoJSON(location_value::text), 4326);
  END IF;

  IF jsonb_typeof(location_value) <> 'array'
     OR jsonb_array_length(location_value) = 0
     OR jsonb_typeof(location_value->0) <> 'array' THEN
    RETURN NULL;
  END IF;

  ring := location_value->0;

  FOR point IN SELECT value FROM jsonb_array_elements(ring)
  LOOP
    IF point ? 'lng' AND point ? 'lat' THEN
      lng := (point->>'lng')::DOUBLE PRECISION;
      lat := (point->>'lat')::DOUBLE PRECISION;
    ELSIF jsonb_typeof(point) = 'array' AND jsonb_array_length(point) >= 2 THEN
      lat := (point->>0)::DOUBLE PRECISION;
      lng := (point->>1)::DOUBLE PRECISION;
    ELSE
      RETURN NULL;
    END IF;

    IF count_points = 0 THEN
      first_lng := lng;
      first_lat := lat;
    END IF;

    last_lng := lng;
    last_lat := lat;
    coords := coords || CASE WHEN coords = '' THEN '' ELSE ',' END || lng || ' ' || lat;
    count_points := count_points + 1;
  END LOOP;

  IF count_points < 3 THEN
    RETURN NULL;
  END IF;

  IF first_lng <> last_lng OR first_lat <> last_lat THEN
    coords := coords || ',' || first_lng || ' ' || first_lat;
    count_points := count_points + 1;
  END IF;

  IF count_points < 4 THEN
    RETURN NULL;
  END IF;

  RETURN ST_SetSRID(ST_GeomFromText('POLYGON((' || coords || '))'), 4326);
EXCEPTION
  WHEN OTHERS THEN
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.gs_polygon_from_location_text(location_text text)
 RETURNS geometry
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
  IF location_text IS NULL OR btrim(location_text) = '' THEN
    RETURN NULL;
  END IF;

  RETURN gs_polygon_from_location(location_text::JSONB);
EXCEPTION
  WHEN OTHERS THEN
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.gs_set_lot_geom_area()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  parsed_geom geometry;
BEGIN
  IF NEW.geom IS NULL AND NEW.location IS NOT NULL THEN
    parsed_geom := gs_polygon_from_location_text(NEW.location::TEXT);
    IF parsed_geom IS NOT NULL AND ST_IsValid(parsed_geom) THEN
      NEW.geom := parsed_geom;
    END IF;
  END IF;

  IF NEW.geom IS NOT NULL THEN
    IF NOT ST_IsValid(NEW.geom) THEN
      RAISE EXCEPTION 'La geometria del lote no es valida';
    END IF;

    NEW.geom := ST_SetSRID(ST_Force2D(NEW.geom), 4326);
    NEW.area_ha := ROUND((ST_Area(NEW.geom::geography) / 10000)::NUMERIC, 4);
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.gs_set_sub_lot_area()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  layout_record lot_layouts%ROWTYPE;
BEGIN
  SELECT *
  INTO layout_record
  FROM lot_layouts
  WHERE id = NEW.layout_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Layout no encontrado';
  END IF;

  IF NEW.lot_id <> layout_record.lot_id OR NEW.company_id <> layout_record.company_id THEN
    RAISE EXCEPTION 'El sublote no pertenece al mismo lote/layout/empresa';
  END IF;

  IF NOT ST_IsValid(NEW.geom) THEN
    RAISE EXCEPTION 'La geometria del sublote no es valida';
  END IF;

  NEW.geom := ST_SetSRID(ST_Force2D(NEW.geom), 4326);
  NEW.area_ha := ROUND((ST_Area(NEW.geom::geography) / 10000)::NUMERIC, 4);

  IF NEW.area_ha <= 0 THEN
    RAISE EXCEPTION 'La superficie del sublote debe ser mayor a 0';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.guard_stock_initial_batch()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE opening stock_initial_openings%ROWTYPE;
BEGIN
  IF TG_OP='INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('stock-initial:'||NEW.company_id,0));
    IF NEW.origin='legacy' AND EXISTS(SELECT 1 FROM stock_initial_openings WHERE company_id=NEW.company_id) THEN
      RAISE EXCEPTION 'Legacy opening cannot follow STOCK_INITIAL; use an audited adjustment' USING ERRCODE='23514';
    END IF;
    IF NEW.origin='stock_initial' THEN
      SELECT * INTO opening FROM stock_initial_openings WHERE id=NEW.stock_initial_id AND company_id=NEW.company_id;
      IF NOT FOUND OR opening.result IS NOT NULL OR NEW.received_date IS DISTINCT FROM opening.effective_date
        OR NEW.created_by IS DISTINCT FROM opening.actor_id OR NEW.available_quantity<>NEW.initial_quantity
        OR NEW.unit_price IS NOT NULL OR NEW.currency IS NOT NULL OR NEW.supplier IS NOT NULL THEN
        RAISE EXCEPTION 'Invalid STOCK_INITIAL batch' USING ERRCODE='23514';
      END IF;
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.stock_initial_id IS NOT NULL THEN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Stock initial batch provenance is immutable' USING ERRCODE='23514'; END IF;
    IF (to_jsonb(NEW)-ARRAY['available_quantity','updated_at']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['available_quantity','updated_at']) THEN
      RAISE EXCEPTION 'Stock initial batch provenance is immutable' USING ERRCODE='23514';
    END IF;
  ELSIF TG_OP='UPDATE' AND NEW.stock_initial_id IS NOT NULL THEN
    RAISE EXCEPTION 'Cannot relabel a batch as STOCK_INITIAL' USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.guard_stock_initial_opening()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('stock-initial:'||NEW.company_id,0));
    IF NEW.effective_date IS DISTINCT FROM (SELECT inventory_control_start_date FROM companies WHERE id=NEW.company_id)
      OR EXISTS(SELECT 1 FROM stock_batches WHERE company_id=NEW.company_id)
      OR EXISTS(SELECT 1 FROM stock_movements WHERE company_id=NEW.company_id) THEN
      RAISE EXCEPTION 'Initial opening requires configured date and empty inventory' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='UPDATE' AND OLD.result IS NULL AND NEW.result IS NOT NULL
    AND (to_jsonb(NEW)-'result')=(to_jsonb(OLD)-'result') THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Stock initial audit is immutable' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.inventory_guard_movement()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE original stock_movements%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'Stock movements are immutable'; END IF;
  IF NEW.movement_type='reversal' THEN
    SELECT * INTO original FROM stock_movements WHERE id=NEW.reversed_movement_id;
    IF NOT FOUND OR original.movement_type<>'consumption'
      OR NEW.quantity<>-original.quantity OR NEW.batch_id<>original.batch_id
      OR NEW.usage_id IS DISTINCT FROM original.usage_id
      OR NEW.company_id<>original.company_id OR NEW.product_id<>original.product_id
    THEN RAISE EXCEPTION 'Invalid stock reversal'; END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.inventory_guard_product_unit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda'
AS $function$
DECLARE reference record; has_history boolean;
BEGIN
  IF TG_OP='UPDATE' AND NEW.unit IS NOT DISTINCT FROM OLD.unit THEN RETURN NEW; END IF;
  NEW.unit:=stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.inventory_normalize_unit(NEW.unit);
  IF NEW.unit IS NULL OR NEW.unit NOT IN ('L','mL','kg','g','unit','bag') THEN
    RAISE EXCEPTION 'Seleccioná una unidad base válida.' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' THEN RETURN NEW; END IF;
  IF NEW.unit=stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.inventory_normalize_unit(OLD.unit) THEN
    NEW.unit:=OLD.unit; RETURN NEW; -- label normalization is not a historical rewrite
  END IF;
  has_history:=COALESCE(OLD.total_quantity,0)<>0 OR COALESCE(OLD.available_quantity,0)<>0;
  FOR reference IN
    SELECT DISTINCT n.nspname,rel.relname,a.attname FROM pg_constraint fk
    JOIN pg_class rel ON rel.oid=fk.conrelid JOIN pg_namespace n ON n.oid=rel.relnamespace
    CROSS JOIN LATERAL unnest(fk.conkey,fk.confkey) AS keys(local_key,foreign_key)
    JOIN pg_attribute a ON a.attrelid=fk.conrelid AND a.attnum=keys.local_key
    JOIN pg_attribute target ON target.attrelid=fk.confrelid AND target.attnum=keys.foreign_key
    WHERE fk.contype='f' AND fk.confrelid='stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.products'::regclass AND target.attname='id'
  LOOP
    EXIT WHEN has_history;
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM %I.%I WHERE %I=$1)',reference.nspname,reference.relname,reference.attname)
      INTO has_history USING OLD.id;
  END LOOP;
  IF has_history THEN
    RAISE EXCEPTION 'La unidad base no puede modificarse porque el producto ya posee movimientos o registros asociados.' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.inventory_inherit_product_unit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda'
AS $function$
DECLARE base_unit text;
BEGIN
  IF NEW.product_id IS NULL THEN RETURN NEW; END IF;
  SELECT unit INTO base_unit FROM stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.products WHERE id=NEW.product_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Producto no disponible.' USING ERRCODE='23503'; END IF;
  IF base_unit IS NULL OR stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.inventory_normalize_unit(base_unit) NOT IN ('L','mL','kg','g','unit','bag') OR
    (NEW.unit IS NOT NULL AND stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.inventory_normalize_unit(NEW.unit) IS DISTINCT FROM stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.inventory_normalize_unit(base_unit)) THEN
    RAISE EXCEPTION 'La unidad debe coincidir con la unidad base del producto.' USING ERRCODE='23514';
  END IF;
  NEW.unit:=base_unit;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.normalize_new_harvest_cycle_area()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.company_id::text || ':' || NEW.lot_id::text, 0));
  IF TG_OP = 'INSERT' THEN
    NEW.area_ha := round(NEW.area_ha, 2);
  ELSIF NEW.area_ha IS DISTINCT FROM OLD.area_ha THEN
    NEW.area_ha := round(NEW.area_ha, 2);
  END IF;
  IF NEW.end_date IS NOT NULL AND NEW.harvest_closure_source IS NULL THEN
    NEW.harvest_closure_source := 'legacy';
  END IF;
  -- Check AFTER taking the same lot lock used by harvest writes. This also covers
  -- a new cycle whose application-level conflict check ran before a reopening.
  IF TG_OP = 'INSERT' THEN
    IF EXISTS (
      SELECT 1 FROM crop_assignments other
      LEFT JOIN sub_lots previous_surface ON previous_surface.id = other.sub_lot_id
      LEFT JOIN sub_lots new_surface ON new_surface.id = NEW.sub_lot_id
      WHERE other.company_id = NEW.company_id AND other.lot_id = NEW.lot_id
        AND EXISTS (SELECT 1 FROM harvest_crop_assignments hca WHERE hca.crop_assignment_id = other.id)
        AND daterange(other.start_date, COALESCE(other.end_date, 'infinity'::date), '[]')
          && daterange(NEW.start_date, COALESCE(NEW.end_date, 'infinity'::date), '[]')
        AND (other.sub_lot_id IS NULL OR NEW.sub_lot_id IS NULL OR other.sub_lot_id = NEW.sub_lot_id
          OR ST_Area(ST_CollectionExtract(ST_Intersection(
            ST_CollectionExtract(ST_MakeValid(previous_surface.geom), 3),
            ST_CollectionExtract(ST_MakeValid(new_surface.geom), 3)), 3)::geography) > 1)
    ) THEN
      RAISE EXCEPTION 'New cycle overlaps a cycle with linked harvests' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.protect_historical_import_audit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Historical import is immutable' USING ERRCODE='23514'; END IF;
  IF OLD.result IS NOT NULL OR (to_jsonb(NEW)-'result') IS DISTINCT FROM (to_jsonb(OLD)-'result') THEN
    RAISE EXCEPTION 'Historical import is immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION stock_initial_test_0f5c1cc634a644a9a8cfc94d07427fda.protect_inventory_impact_mode()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_TABLE_NAME='crop_assignments' AND OLD.inventory_impact_mode='HISTORICAL_NO_STOCK'
     AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION 'Historical productive cycles cannot be recalculated' USING ERRCODE='23514';
  END IF;
  IF NEW.inventory_impact_mode IS DISTINCT FROM OLD.inventory_impact_mode
     OR NEW.historical_import_id IS DISTINCT FROM OLD.historical_import_id THEN
    RAISE EXCEPTION 'Inventory impact mode and import provenance are immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

